const raw = $input.first()?.json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

// 1. Verifica Challenge da Slack Events API (url_verification)
if (body.type === 'url_verification' && body.challenge) {
  return [
    {
      json: {
        is_slack_challenge: true,
        challenge: String(body.challenge),
        channel_type: 'slack'
      }
    }
  ];
}

let channelType = 'telegram';
let externalUserId = 'anon-user';
let chatId = 'anon-chat';
let displayName = 'Contribuinte Fiscália';
let messageText = '';

// 2. Detecção de Payload Telegram (Update / Message / CallbackQuery)
if (body.message || body.edited_message || body.callback_query) {
  const msg = body.message || body.edited_message || body.callback_query?.message || {};
  const from = body.callback_query?.from || msg.from || {};
  channelType = 'telegram';
  externalUserId = String(from.id || msg.chat?.id || 'tg-demo-user');
  chatId = String(msg.chat?.id || from.id || 'tg-demo-chat');
  displayName = [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'Usuário Telegram';
  messageText = String(body.callback_query?.data || msg.text || '').trim();
}
// 3. Detecção de Payload Slack Events API ou Slash Commands
else if (body.event || body.command || body.team_id || body.channel_type === 'slack' || String(raw.webhookUrl || '').includes('fiscalia-slack')) {
  channelType = 'slack';
  if (body.event) {
    externalUserId = String(body.event.user || 'slack-demo-user');
    chatId = String(body.event.channel || 'slack-demo-channel');
    displayName = String(body.event.user_profile?.real_name || body.event.username || `Slack User ${externalUserId}`);
    messageText = String(body.event.text || '').replace(/<@[A-Z0-9]+>/g, '').trim();
  } else if (body.command) {
    externalUserId = String(body.user_id || 'slack-demo-user');
    chatId = String(body.channel_id || 'slack-demo-channel');
    displayName = String(body.user_name || 'Usuário Slack');
    messageText = `${body.command} ${body.text || ''}`.trim();
  } else {
    externalUserId = String(body.external_user_id || body.user_id || 'slack-demo-user');
    chatId = String(body.chat_id || body.channel_id || 'slack-demo-channel');
    displayName = String(body.display_name || body.user_name || 'Usuário Slack');
    messageText = String(body.message_text || body.text || '').trim();
  }
}
// 4. Payload direto via cURL / Testes Automatizados
else {
  channelType = String(body.channel_type || 'telegram').toLowerCase() === 'slack' ? 'slack' : 'telegram';
  externalUserId = String(body.external_user_id || body.user_id || 'demo-user-001');
  chatId = String(body.chat_id || externalUserId);
  displayName = String(body.display_name || 'Empresa Demo Fiscália');
  messageText = String(body.message_text || body.text || body.query || '/resumo').trim();
}

const sessionId = `${channelType}:${externalUserId}`;

// Identifica rota: /setores, /resumo, /simular_dou ou agente_conversacional
let routeType = 'agente_conversacional';
const lowerMsg = messageText.toLowerCase();
if (lowerMsg.startsWith('/setores') || lowerMsg.startsWith('!setores')) {
  routeType = 'cmd_setores';
} else if (lowerMsg.startsWith('/resumo') || lowerMsg.startsWith('!resumo')) {
  routeType = 'cmd_resumo';
} else if (lowerMsg.startsWith('/simular_dou') || lowerMsg.startsWith('!simular_dou')) {
  routeType = 'cmd_simular_dou';
}

return [
  {
    json: {
      is_slack_challenge: false,
      channel_type: channelType,
      external_user_id: externalUserId,
      chat_id: chatId,
      display_name: displayName,
      message_text: messageText,
      session_id: sessionId,
      route_type: routeType
    }
  }
];

const norm = $('Normalizar Payload Multi-Canal (Telegram & Slack)').first().json;
const sqlCtx = $input.first()?.json || {};

const subscribedSlugs = Array.isArray(sqlCtx.subscribed_sector_slugs)
  ? sqlCtx.subscribed_sector_slugs
  : [];

return [
  {
    json: {
      ...norm,
      user_id: sqlCtx.user_id,
      business_context: sqlCtx.business_context || 'Não informado',
      subscribed_sector_slugs: subscribedSlugs,
      subscribed_sectors_detail: sqlCtx.subscribed_sectors_detail || [],
      available_catalog: sqlCtx.available_catalog || [],
      recent_history: sqlCtx.recent_history || []
    }
  }
];

const ctx = $input.first().json;
const rawArgs = ctx.message_text.replace(/^(\/|!)setores\s*/i, '').trim();

const aliasMap = {
  tecnologia: 'tecnologia_saas',
  tecnologia_ti: 'tecnologia_saas',
  saas: 'tecnologia_saas',
  ti: 'tecnologia_saas',
  saude: 'saude_servicos_medicos',
  agro: 'agronegocio',
  varejo: 'varejo_comercio',
  comercio: 'varejo_comercio',
  industria: 'industria_manufatura',
  industria_transformacao: 'industria_manufatura',
  construcao: 'construcao_imobiliario',
  imobiliario: 'construcao_imobiliario',
  transporte: 'transporte_logistica',
  logistica: 'transporte_logistica',
  financeiro: 'servicos_financeiros',
  financeiro_seguros: 'servicos_financeiros',
  alimentacao: 'alimentacao_hotelaria',
  bares_restaurantes_hotelaria: 'alimentacao_hotelaria',
  servicos_profissionais: 'profissoes_regulamentadas',
  profissoes: 'profissoes_regulamentadas',
  energia: 'energia_combustiveis_telecom',
  energia_combustiveis: 'energia_combustiveis_telecom'
};

const normalizeSlug = (s) => aliasMap[s] || s;

let action = 'list_only';
let slugs = [];

if (rawArgs) {
  const parts = rawArgs.split(/\s+/);
  const firstWord = parts[0].toLowerCase();
  if (['add', 'set', 'remove', 'clear'].includes(firstWord)) {
    action = firstWord;
    slugs = parts.slice(1).join(',').split(/[\s,;]+/).map((s) => normalizeSlug(s.trim().toLowerCase())).filter(Boolean);
  } else {
    action = 'add';
    slugs = rawArgs.split(/[\s,;]+/).map((s) => normalizeSlug(s.trim().toLowerCase())).filter(Boolean);
  }
}

const pgSectorArray = `{${slugs.map((s) => `"${s.replace(/"/g, '')}"`).join(',')}}`;

return [
  {
    json: {
      ...ctx,
      cmd_action: action,
      cmd_slugs: slugs,
      pg_sector_array: pgSectorArray
    }
  }
];

const ctx = $('Parsear Comando /setores').first().json;
const res = $input.first()?.json?.subscription_result || {};
const catalog = Array.isArray(ctx.available_catalog) ? ctx.available_catalog : [];
const currentSlugs = Array.isArray(res.subscribed_sector_slugs) ? res.subscribed_sector_slugs : ctx.subscribed_sector_slugs;
const currentNames = Array.isArray(res.subscribed_sector_names) ? res.subscribed_sector_names : [];

const catalogLines = catalog.map((c) => {
  const isSub = currentSlugs.includes(c.slug);
  return `${isSub ? '✅' : '▫️'} \`${c.slug}\`\n   *${c.name}* _(CNAEs: ${(c.cnae_examples || []).slice(0, 2).join(', ')})_`;
}).join('\n\n');

const replyText = [
  `🏛️ *Fiscália — Gestão de Setores Monitorados (LC 214/2025)*`,
  ``,
  `👤 *Contribuinte:* ${ctx.display_name} (\`${ctx.session_id}\`)`,
  `📌 *Setores Ativos (${currentSlugs.length}):* ${currentNames.length > 0 ? currentNames.join(', ') : 'Nenhum setor assinado ainda'}`,
  res.action_applied && res.action_applied !== 'list_only' ? `🔄 *Ação executada:* \`${res.action_applied}\`` : null,
  ``,
  `📋 *Catálogo Canônico dos 12 Setores da Reforma Tributária (LC 214/2025):*`,
  ``,
  catalogLines,
  ``,
  `💡 *Como atualizar seus setores rapidamente:*`,
  `• Adicionar setores: \`/setores add tecnologia_saas profissoes_regulamentadas\``,
  `• Substituir lista: \`/setores set saude_servicos_medicos educacao\``,
  `• Remover setor: \`/setores remove varejo_comercio\``,
  `• Limpar todos: \`/setores clear\``,
  ``,
  `⚖️ _Disclaimer Legal: Informações baseadas na LC 214/2025 para fins de inteligência tributária. Não substitui parecer jurídico ou contábil formal._`
].filter((line) => line !== null).join('\n');

return [
  {
    json: {
      ...ctx,
      subscribed_sector_slugs: currentSlugs,
      reply_text: replyText,
      response_type: 'command_setores'
    }
  }
];

const ctx = $('Consolidar Contexto do Usuário').first().json;
const data = $input.first()?.json || {};
const matrixRows = Array.isArray(data.matrix_rows) ? data.matrix_rows : [];
const ordRows = Array.isArray(data.ordinances_rows) ? data.ordinances_rows : [];

let matrixSection = '';
if (matrixRows.length === 0) {
  matrixSection = '⚠️ Você ainda não possui setores vinculados ao seu perfil. Use `/setores add tecnologia_ti` (ou outro setor da LC 214) para personalizar seu painel.';
} else {
  matrixSection = matrixRows.map((m) => [
    `🔹 *${m.name}* (\`${m.slug}\`)`,
    `   • *Regime LC 214:* ${m.regime_type} (Redução: ${m.reduction_percent}% | Alíquota Efetiva Est.: ${m.estimated_effective_rate})`,
    `   • *Base Legal:* ${m.legal_basis}`,
    `   • *Créditos IBS/CBS:* ${m.credit_rules}`
  ].join('\n')).join('\n\n');
}

const ordSection = ordRows.length === 0
  ? 'Nenhuma portaria recente encontrada.'
  : ordRows.map((o) => `• *[${o.grau_urgencia}] ${o.act_number}* (${o.published_at}) — ${o.resumo_geral}\n  🔗 [Link Oficial Receita/DOU](${o.official_url})`).join('\n\n');

const replyText = [
  `📊 *Fiscália — Panorama Tributário Setorial (/resumo)*`,
  ``,
  `*(a) Setor(es) Analisado(s) & Situação Atual:*`,
  matrixSection,
  ``,
  `*(b) Cronograma de Transição 2026–2033 (LC 214/2025):*`,
  `• *2026:* Alíquota-teste (CBS 0,9% + IBS 0,1%) compensável com PIS/Cofins e destaque obrigatório em NF-e/NFS-e.`,
  `• *2027:* Entrada plena da CBS e extinção do PIS/Cofins; início do Split Payment inteligente.`,
  `• *2029–2032:* Redução progressiva do ICMS/ISS (10% a 40%) e escalonamento do IBS.`,
  `• *2033:* Vigência integral do IVA Dual (IBS + CBS) e extinção definitiva do ICMS/ISS.`,
  ``,
  `*(c) Portarias e Atos Normativos Recentes (DOU / RFB):*`,
  ordSection,
  ``,
  `*(d) Ação Recomendada:*`,
  `Parametrizar o ERP e layouts de documentos fiscais eletrônicos (cClassTrib / CST-IBS/CBS) conforme os atos normativos listados acima.`,
  ``,
  `⚖️ _Disclaimer Legal: Este panorama é gerado por inteligência artificial com base na LC 214/2025 e atos públicos da RFB/DOU, possuindo caráter estritamente informativo. Não substitui consultoria contábil ou parecer jurídico formal._`
].join('\n');

return [
  {
    json: {
      ...ctx,
      reply_text: replyText,
      response_type: 'command_resumo'
    }
  }
];

const ctx = $('Consolidar Contexto do Usuário').first().json;
const wf1Res = $input.first()?.json || {};
const ok = !wf1Res.error;

const replyText = [
  `🚨 *Fiscália — Simulação Ao Vivo do Monitor DOU (/simular_dou)*`,
  ``,
  ok
    ? `✅ O *Workflow 01 (Monitor Proativo DOU & RFB)* foi acionado com sucesso via \`POST http://localhost:5678/webhook/simular-dou\` (\`{"action": "replay"}\`).`
    : `⚠️ O disparo para \`http://localhost:5678/webhook/simular-dou\` retornou aviso: \`${wf1Res.error?.message || 'Verifique se o Workflow 01 está ativo no n8n'}\`.`,
  ``,
  `📡 *O que acontece agora:*`,
  `1. O Workflow 01 processa os atos normativos da Receita Federal / DOU.`,
  `2. Realiza a triagem estruturada e o cruzamento com os setores inscritos de cada contribuinte via \`get_consolidated_subscribers_for_ordinance\`.`,
  `3. Dispara alertas consolidados (zero spam) nos canais ativos.`,
  ``,
  `⚖️ _Disclaimer Legal: Simulação técnica de monitoramento normativo da Reforma Tributária (LC 214/2025)._`
].join('\n');

return [
  {
    json: {
      ...ctx,
      simulation_response: wf1Res,
      reply_text: replyText,
      response_type: 'command_simular_dou'
    }
  }
];

const ctx = $input.first().json;
const text = (ctx.message_text || '').toLowerCase();
const catalog = Array.isArray(ctx.available_catalog) ? ctx.available_catalog : [];

// Detecta se o usuário mencionou algum dos 12 setores na pergunta
const mentionedSlugs = [];
for (const item of catalog) {
  const slugWords = item.slug.split('_');
  if (text.includes(item.slug) || text.includes(item.name.toLowerCase()) || slugWords.some((w) => w.length > 3 && text.includes(w))) {
    mentionedSlugs.push(item.slug);
  }
}

// Heurística semântica extra para termos comuns
const keywordMap = {
  tecnologia_saas: ['software', 'saas', 'ti', 'cloud', 'dados', 'sistema', 'tecnologia'],
  saude_servicos_medicos: ['hospital', 'clinica', 'clínica', 'medico', 'médico', 'medicamento', 'farmacia', 'plano de saude', 'saude', 'saúde'],
  educacao: ['escola', 'faculdade', 'universidade', 'ensino', 'curso', 'educacao', 'educação'],
  agronegocio: ['agro', 'fazenda', 'soja', 'pecuaria', 'produtor rural', 'insumo'],
  construcao_imobiliario: ['obra', 'incorporadora', 'imovel', 'imóvel', 'aluguel', 'locacao', 'construcao', 'construção'],
  transporte_logistica: ['frete', 'caminhao', 'logistica', 'logística', 'transporte', 'passageiro'],
  profissoes_regulamentadas: ['advocacia', 'contabilidade', 'contador', 'consultoria', 'engenharia', 'arquitetura'],
  varejo_comercio: ['loja', 'e-commerce', 'varejo', 'supermercado', 'comercio', 'comércio'],
  industria_manufatura: ['fabrica', 'fábrica', 'industria', 'indústria', 'manufatura', 'exportacao'],
  servicos_financeiros: ['banco', 'fintech', 'seguro', 'credito', 'financeira', 'split payment'],
  energia_combustiveis_telecom: ['combustivel', 'energia', 'solar', 'gas', 'etanol', 'monofasico', 'telecom'],
  alimentacao_hotelaria: ['restaurante', 'bar', 'hotel', 'turismo', 'evento', 'gorjeta']
};

for (const [slug, words] of Object.entries(keywordMap)) {
  if (words.some((w) => text.includes(w)) && !mentionedSlugs.includes(slug)) {
    mentionedSlugs.push(slug);
  }
}

const targetSlugs = Array.from(new Set([...mentionedSlugs, ...(ctx.subscribed_sector_slugs || [])]));
const wantsSubscriptionUpdate = /(cadastrar|assinar|monitorar|adicionar setor|meu setor é|minha empresa é|atuo no setor)/i.test(text);
const wantsLiveDou = /(dou de hoje|tempo real|saiu hoje|publicado hoje)/i.test(text);

return [
  {
    json: {
      ...ctx,
      target_sector_slugs: targetSlugs,
      mentioned_sector_slugs: mentionedSlugs,
      wants_subscription_update: wantsSubscriptionUpdate,
      wants_live_dou: wantsLiveDou,
      tool_name: 'consultar_situacao_e_cronograma_setorial',
      sector_slugs: targetSlugs,
      query: ctx.message_text
    }
  }
];

const prep = $('Preparar Orquestração ReAct & Tools').first().json;
const toolBOutput = $input.first()?.json || {};

return [
  {
    json: {
      ...prep,
      tool_b_results: toolBOutput.results || [],
      tool_name: 'buscar_portarias_por_setor_rag',
      sector_slugs: prep.target_sector_slugs,
      query: prep.message_text
    }
  }
];

const prev = $('Preparar Chamada Tool C (RAG pgvector)').first().json;
const toolCOutput = $input.first()?.json || {};
const toolBResults = Array.isArray(prev.tool_b_results) ? prev.tool_b_results : [];
const toolCResults = Array.isArray(toolCOutput.results) ? toolCOutput.results : [];

const apiKey = ($env.GEMINI_API_KEY || '').trim();
const modelName = ($env.GEMINI_MODEL_AGENT || 'gemini-2.5-flash').trim();

// Definição das 4 Tools ReAct declaradas para o modelo Gemini (Function Calling)
const geminiToolsSpec = [
  {
    name: 'gerenciar_setor_usuario',
    description: 'Adiciona, define, remove ou limpa os setores econômicos monitorados pelo usuário (LC 214/2025) e atualiza seu contexto de negócio.'
  },
  {
    name: 'consultar_situacao_e_cronograma_setorial',
    description: 'Consulta a matriz tributária da LC 214/2025 para os setores solicitados, retornando regime, alíquota efetiva, redução, base legal, regras de crédito e cronograma 2026-2033.'
  },
  {
    name: 'buscar_portarias_por_setor_rag',
    description: 'Busca semântica vetorial (pgvector 768d) nas portarias e instruções normativas da RFB/DOU filtrada pelos setores do usuário + escopo GERAL.'
  },
  {
    name: 'verificar_dou_tempo_real',
    description: 'Consulta em tempo real o portal de Normas da Receita Federal / DOU (timeout 8s) extraindo os 5 atos mais recentes do dia.'
  }
];

const systemInstruction = `Você é o Fiscália, Consultor Tributário Inteligente especializado na Reforma Tributária Brasileira (Lei Complementar nº 214/2025, IBS, CBS e Imposto Seletivo) e nos atos normativos da Receita Federal (RFB) e Diário Oficial da União (DOU).

REGRAS OBRIGATÓRIAS DE RESPOSTA:
1. Estruture SEMPRE a resposta exatamente nas 4 seções abaixo:
   *(a) Setor Analisado & Situação Atual*
   *(b) Alíquotas, Regimes Diferenciados e Cronograma 2026–2033*
   *(c) Portarias Recentes (com links oficiais)*
   *(d) Ação Recomendada*
2. Ao final, inclua obrigatoriamente o *Disclaimer Legal* informando que a análise tem caráter informativo baseado na LC 214/2025 e não substitui parecer contábil ou jurídico formal.
3. Utilize exclusivamente os dados factuais da Matriz LC 214 e das Portarias RAG fornecidos no contexto abaixo. Nunca invente números de portarias ou links.`;

const promptContext = JSON.stringify({
  usuario: {
    user_id: prev.user_id,
    nome: prev.display_name,
    canal: prev.channel_type,
    setores_assinados: prev.subscribed_sector_slugs,
    contexto_negocio: prev.business_context
  },
  pergunta_usuario: prev.message_text,
  historico_recente: prev.recent_history,
  tools_disponiveis_subworkflow_03: geminiToolsSpec,
  tool_b_matriz_lc214: toolBResults,
  tool_c_portarias_rag: toolCResults
}, null, 2);

let agentReply = '';
let usedModel = 'deterministic_structured_fallback';

if (apiKey && apiKey !== 'your_gemini_api_key_here') {
  try {
    const geminiRes = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/${modelName}:generateContent?key=${apiKey}`,
      headers: { 'Content-Type': 'application/json' },
      body: {
        systemInstruction: {
          parts: [{ text: systemInstruction }]
        },
        contents: [
          {
            role: 'user',
            parts: [{ text: `Responda à consulta do contribuinte com base nos dados oficiais extraídos pelas Tools do Sub-Workflow 03 do Fiscália:\n\n${promptContext}` }]
          }
        ],
        generationConfig: {
          temperature: 0.2,
          maxOutputTokens: 1600
        }
      },
      json: true,
      timeout: 20000
    });

    const candidateText = geminiRes?.candidates?.[0]?.content?.parts?.map((p) => p.text || '').join('\n').trim();
    if (candidateText) {
      agentReply = candidateText;
      usedModel = modelName;
    }
  } catch (err) {
    usedModel = `fallback_after_error: ${err.message}`;
  }
}

if (!agentReply) {
  const primarySector = toolBResults[0] || {
    sector_name: 'Setor Geral / Múltiplos Setores (LC 214/2025)',
    sector_slug: (prev.target_sector_slugs || [])[0] || 'geral',
    regime_type: 'Regime Padrão IVA Dual (IBS + CBS)',
    estimated_effective_rate: '~26,5% (alíquota de referência padrão)',
    reduction_percent: 0,
    legal_basis: 'LC 214/2025',
    credit_rules: 'Não cumulatividade plena com crédito financeiro amplo sobre aquisições tributadas.',
    key_obligations: ['Destaque de CBS (0,9%) e IBS (0,1%) em 2026', 'Adaptação ao Split Payment'],
    transition_schedule: {
      '2026': 'Alíquota-teste CBS 0,9% + IBS 0,1% compensável com PIS/Cofins',
      '2027': 'Vigência plena da CBS e extinção do PIS/Cofins',
      '2029_2032': 'Transição gradual do ICMS/ISS para o IBS',
      '2033': 'Vigência integral do novo sistema tributário'
    }
  };

  const sectorListSummary = toolBResults.length > 0
    ? toolBResults.map((s) => `• *${s.sector_name}* (\`${s.sector_slug}\`): ${s.regime_type} — Base Legal: ${s.legal_basis}`).join('\n')
    : `• *${primarySector.sector_name}*: ${primarySector.regime_type} (${primarySector.legal_basis})`;

  const scheduleObj = primarySector.transition_schedule || {};
  const scheduleLines = Object.entries(scheduleObj).map(([yr, desc]) => `  - *${yr}:* ${desc}`).join('\n');

  const ordLines = toolCResults.length > 0
    ? toolCResults.slice(0, 3).map((o) => `• *${o.act_number}* (${o.published_at || '2025/2026'}) — _${o.title}_\n  Resumo: ${o.resumo_geral}\n  Vigência: ${o.previsao_vigencia || 'Conforme ato'} | 🔗 [Link Oficial](${o.official_url})`).join('\n\n')
    : '• Consulte os atos normativos atualizados da RFB/DOU através do comando `/resumo`.';

  agentReply = [
    `🤖 *Consultor Tributário Fiscália — Análise Técnica LC 214/2025*`,
    ``,
    `*(a) Setor Analisado & Situação Atual*`,
    sectorListSummary,
    `Regras de Crédito: ${primarySector.credit_rules}`,
    ``,
    `*(b) Alíquotas, Regimes Diferenciados e Cronograma 2026–2033*`,
    `• *Alíquota Efetiva Estimada:* ${primarySector.estimated_effective_rate} (Redução legal: ${primarySector.reduction_percent}%)`,
    `• *Cronograma de Transição:*`,
    scheduleLines || '  - 2026 a 2033: Transição escalonada CBS/IBS conforme LC 214/2025.',
    ``,
    `*(c) Portarias Recentes (com links oficiais)*`,
    ordLines,
    ``,
    `*(d) Ação Recomendada*`,
    `1. Revisar a classificação fiscal (NCM/NBS e \`cClassTrib\`) nas emissões de NF-e/NFS-e para 2026.\n2. Avaliar o impacto de fluxo de caixa do *Split Payment* e mapear créditos de IBS/CBS na cadeia de fornecedores.`,
    ``,
